import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Extract own and opponent moves as compact strings for fast pattern checks.
    own = []
    opp = []
    for h in history:
        own.append(h[0])
        opp.append(h[1])

    opp_def = 0
    own_def = 0
    last10_opp_def = 0
    last10_own_def = 0
    start10 = n - 10
    if start10 < 0:
        start10 = 0
    for i in range(n):
        if opp[i] == 'D':
            opp_def += 1
            if i >= start10:
                last10_opp_def += 1
        if own[i] == 'D':
            own_def += 1
            if i >= start10:
                last10_own_def += 1

    coop = n - opp_def

    # Detect long runs at the end.
    tail_opp_def = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            tail_opp_def += 1
        else:
            break

    tail_opp_c = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'C':
            tail_opp_c += 1
        else:
            break

    last_opp = opp[-1]

    # Opponent never defected: stay cooperative but add rare, strategic late probes.
    if opp_def == 0:
        if n >= 95:
            r = rng.random()
            if r < 0.08:
                return 'D'
        return 'C'

    # Opponent never cooperated: always defect.
    if coop == 0:
        return 'D'

    # Short-term: mirror with mild stochastic forgiveness and noise resistance.
    if last_opp == 'C':
        # If opponent has been extremely defection-heavy recently, punish.
        if last10_opp_def >= 6:
            return 'D'
        # If we've been exploited (we cooped a lot while they defected), occasionally retaliate.
        if last10_opp_def >= 3 and last10_own_def <= 1:
            if rng.random() < 0.35:
                return 'D'
        # Reward sustained cooperation. Rare probe late if opponent is saintly.
        if n >= 90 and opp_def <= 2:
            if rng.random() < 0.12:
                return 'D'
        return 'C'
    else:
        # Opponent defected last round.
        # Long opponent defection streak: keep defecting.
        if tail_opp_def >= 3:
            # Occasionally test forgiveness in case of noise, but mostly D.
            if tail_opp_def >= 6:
                return 'D'
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        # Opponent mostly cooperative overall: retaliate once, then revert.
        if opp_def * 4 <= n:
            if own_def > 0 and own[-1] == 'D':
                # We already punished; revert to cooperation to avoid spiral.
                return 'C'
            return 'D'
        # Moderate defection rate: retaliate, with reduced randomness.
        return 'D'
